class Solution {
public:
    vector<int> bestPowerArray(vector<int>& A) {
        vector<vector<int>> groups{A}; vector<int> res;
        for (int i = 0; i < 20; i++) {
            int b = 19 - i, x = 0;
            for (size_t gi = 0; gi < groups.size(); gi++) {
                vector<int> w, o;
                for (int v : groups[gi]) (v >> b & 1 ? w : o).push_back(v);
                if (o.empty()) { x += w.size(); continue; }
                x += w.size();
                if (!w.empty()) { groups[gi] = o; groups.insert(groups.begin() + gi, w); }
                break;
            }
            res.push_back(x);
        }
        return res;
    }
};

